Based on the provided `test/res.send.js` file, when `res.send()` is called with a JavaScript **Object**, Express automatically handles it by:

1.  **Setting the Content-Type:** It sets the `Content-Type` header to `application/json; charset=utf-8`.
2.  **Serializing the Data:** It converts the object into a JSON string (e.g., `{ name: 'tobi' }` becomes `'{"name":"tobi"}'`).

This behavior is demonstrated in the following test case:

```javascript
describe('.send(Object)', function(){
  it('should send as application/json', function(done){
    var app = express();

    app.use(function(req, res){
      res.send({ name: 'tobi' });
    });

    request(app)
    .get('/')
    .expect('Content-Type', 'application/json; charset=utf-8')
    .expect(200, '{"name":"tobi"}', done)
  })
})
```
